/**
 * M6/M8 Workflow: pending-queue drain over the wire graph extracted in M4.
 *
 * Deterministic by construction: the only I/O is the awaited `executeNode`
 * Activity call (via `proxyActivities`); no Date.now()/Math.random()/fs/etc.
 * anywhere in this file. `resolveDestinations` and `runFlow` are plain,
 * side-effect free functions so they can be unit-tested directly (see A2
 * answer #2 in the M6 handoff for the grep proving this).
 *
 * Fan-out scope decision (issue #5): the M6 single-path walk followed only
 * the first destination of the first send. This has been replaced by a
 * pending-queue drain that follows EVERY destination on EVERY port of EVERY
 * send emitted by a node, so a true branch (A -> B and A -> C) executes both
 * branches. `resolveNext` (singular) was replaced by `resolveDestinations`
 * (plural, returns an array) rather than kept alongside it - the old
 * single-id return value has no remaining caller once the loop walks a
 * queue instead of a single `node`/`msg` pair, so keeping both would just be
 * dead/duplicate routing logic.
 *
 * Execution stays strictly sequential: the queue is drained one
 * `executeNode` call at a time (`await` inside the loop), never in
 * parallel - see the M6/M8 handoffs for why (no parallel Activities is an
 * explicit scope boundary, not an oversight). Fan-in (two branches
 * converging on the same downstream node) and loops (a wire cycling back to
 * an earlier node) are therefore both out of scope: fan-in is simply never
 * merged/deduplicated (the shared node is invoked once per incoming branch),
 * and a loop in `graph` would drain forever. Neither is guarded against here.
 */

"use strict";

const { proxyActivities, ApplicationFailure } = require("@temporalio/workflow");

// Non-retryable node/business errors (M5 `activities.js` codes). These are
// never worth retrying: a bad wire graph, a stale flow deploy, or a node's
// own thrown error will fail identically on every retry attempt.
const NON_RETRYABLE_CODES = new Set([
    "FLOW_VERSION_MISMATCH",
    "NODE_NOT_FOUND",
    "NODE_ERROR",
    "NODE_TIMEOUT"
]);

/**
 * Given the wire graph and a single send emitted by `nodeId`, resolve ALL
 * destination node ids wired to the port the message was sent on. Returns
 * an empty array when there is nothing further to route to (end of path on
 * that port, unwired port, or `send` itself is undefined/null).
 *
 * @param {Object<string, Array<Array<string>>>} graph
 * @param {string} nodeId - the node that produced `send`
 * @param {{port:number, msg:object}} [send]
 * @returns {string[]}
 */
function resolveDestinations(graph, nodeId, send) {
    if (!send) {
        return [];
    }
    const wires = graph && graph[nodeId];
    const port = wires && wires[send.port];
    return port || [];
}

/**
 * Pure routing loop, parameterized over `executeNode` so it can be unit
 * tested with a mock Activity function - the actual Temporal Workflow entry
 * point (`executeFlow` below) supplies the real, Temporal-proxied Activity.
 *
 * Walks a FIFO pending-queue of `{nodeId, msg}` work items instead of a
 * single `node`/`msg` pair (issue #5): every send emitted by a node fans out
 * to every destination on the port it sent on, and each destination is
 * pushed onto the queue. The queue is drained strictly one item at a time -
 * no parallel `executeNode` calls - so ordering stays deterministic
 * (breadth-first over the fan-out tree) even though it now visits more than
 * one path.
 *
 * Node-RED's own `preRoute` hook already fires once PER WIRED DESTINATION,
 * not once per `node.send()` call (`Flow.js` `handleOnSend`/`handlePreRoute`:
 * "preRoute - called once for each SendEvent object in turn"). Capture (M2,
 * unmodified here) records one `{port, msg}` entry per destination, so
 * `result.sends` already contains N entries for a port with N wired
 * destinations - it is not one logical send that this loop must additionally
 * fan out via the graph. Resolving destinations again per entry would
 * multiply invocations (N sends x N graph destinations). This loop instead
 * dedupes `sends` down to one representative message per distinct port
 * before resolving that port's destinations from `graph`, so each wired
 * destination is invoked exactly once.
 *
 * Any Activity result carrying `error` ends the run immediately by throwing
 * an `ApplicationFailure` marked `nonRetryable: true` (approach (a) from the
 * M6 plan - see handoff for the rejected alternative and why). This still
 * aborts the ENTIRE run, including any other branches still queued: a fan-out
 * flow with an error in one branch does not continue draining sibling
 * branches, matching the M6 fail-loud behavior for the linear case.
 *
 * @param {{executeNode:function, graph:object, flowVersion:string, startNode:string, startMsg:*}} input
 * @returns {Promise<{flowVersion:string, lastNode:(string|undefined)}>}
 */
async function runFlow({ executeNode, graph, flowVersion, startNode, startMsg }) {
    const pending = startNode ? [{ nodeId: startNode, msg: startMsg }] : [];
    let lastNode;

    while (pending.length) {
        const current = pending.shift();
        const result = await executeNode({ flowVersion, nodeId: current.nodeId, msg: current.msg });
        if (result.error) {
            throw ApplicationFailure.create({
                message: `node ${current.nodeId} failed: [${result.error.code}] ${result.error.message}`,
                type: result.error.code,
                nonRetryable: NON_RETRYABLE_CODES.has(result.error.code),
                details: [result.error]
            });
        }
        lastNode = current.nodeId;
        const sends = result.sends || [];
        const msgByPort = new Map();
        for (const send of sends) {
            if (!msgByPort.has(send.port)) {
                msgByPort.set(send.port, send.msg);
            }
        }
        for (const [port, msg] of msgByPort) {
            const destinations = resolveDestinations(graph, current.nodeId, { port, msg });
            for (const destinationId of destinations) {
                pending.push({ nodeId: destinationId, msg });
            }
        }
    }

    return { flowVersion, lastNode };
}

// Activity timeout: 30s, well above Capture's DEFAULT_TIMEOUT_MS (5s, see
// capture.js) so a NODE_TIMEOUT from Capture always surfaces first, instead
// of Temporal killing the Activity call before Capture's own timer fires
// (see M6 handoff A2 #4 for the full ordering argument).
const { executeNode } = proxyActivities({
    startToCloseTimeout: "30s",
    // Retry policy for transient infra failures (thrown Activity errors,
    // e.g. worker crash mid-call). Node-level business errors never throw
    // here - executeNode always resolves - so this policy only ever governs
    // real infra retries, not node.error()/timeout retries (see A2 #1).
    retry: { maximumAttempts: 3, initialInterval: "1s", backoffCoefficient: 2 }
});

/**
 * Temporal Workflow entry point. Registered by `worker.js` under this
 * function's name.
 * @param {{graph:object, flowVersion:string, startNode:string, startMsg:*}} input
 */
async function executeFlow(input) {
    return runFlow({ executeNode, graph: input.graph, flowVersion: input.flowVersion, startNode: input.startNode, startMsg: input.startMsg });
}

module.exports = { resolveDestinations, runFlow, executeFlow };
